// Generated by tools/grammar-build.js from grammar/source.json + grammar/corrections.json — do not edit by hand.
window.GRAMMAR = {"version":"2026.10 - revised original edition","steps":[{"n":1,"level":"A1.1","title":"People, names and first verbs","goal":"Introduce yourself and recognize informal/polite forms.","formula":"ich + verb + information","explanations":["Use ich, du and Sie with the correct verb form. A German present-tense verb changes with the subject.","With ich use -e for many verbs; du often uses -st; polite Sie uses -en. The verb sein is irregular."],"notes":["Meaning comes first: ask who is speaking before choosing the ending.","ich heiße, du heißt, Sie heißen: forms belong to different people.","Use the fixed polite pair Guten Tag! / Auf Wiedersehen! only in appropriate contexts.","The form Sie is written with a capital S when it means polite you."],"examples":[{"de":"Ich lerne heute Deutsch.","en":"I'm learning German today."},{"de":"Du kommst aus Portugal.","en":"You come from Portugal."},{"de":"Sind Sie Frau Richter?","en":"Are you Ms Richter?"}],"trap":{"wrong":"Ich bin lerne Deutsch.","correct":"Ich lerne Deutsch.","why":"Do not combine bin with an ordinary present-tense verb."},"challenge":"Say four true sentences: your name, country, town and language. Then change two sentences to du/Sie questions.","questions":[{"id":"G01-01","step":1,"kind":"mc","prompt":"Ich ___ Leila.","answer":"bin","explanation":"ich uses bin.","options":["bin","bist","ist"]},{"id":"G01-02","step":1,"kind":"mc","prompt":"Du ___ aus Polen.","answer":"kommst","explanation":"du typically takes -st.","options":["kommst","kommen","komme"]},{"id":"G01-03","step":1,"kind":"mc","prompt":"Frau Keller, ___ Sie Deutsch?","answer":"lernen","explanation":"Polite Sie uses the infinitive-shaped plural form.","options":["lernen","lernst","lernt"]},{"id":"G01-04","step":1,"kind":"mc","prompt":"Wie ___ du?","answer":"heißt","explanation":"With du, heißen becomes heißt.","options":["heißt","heißen","heiße"]},{"id":"G01-05","step":1,"kind":"mc","prompt":"Das ___ Herr Lang.","answer":"ist","explanation":"Das takes the third-person singular ist.","options":["ist","bin","sind"]},{"id":"G01-06","step":1,"kind":"mc","prompt":"___ heißen Sie?","answer":"Wie","explanation":"The idiomatic question for someone's name starts with Wie.","options":["Wie","Wo","Wer"]},{"id":"G01-F1","step":1,"kind":"fill","prompt":"Ich ___ Deutsch. (lernen)","answer":"lerne","explanation":"ich takes -e."},{"id":"G01-F2","step":1,"kind":"fill","prompt":"Wie ___ Sie? (heißen)","answer":"heißen","explanation":"Polite Sie uses heißen."}],"tasks":[{"id":"G01-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Ich bin lerne Deutsch.","model":"Ich lerne Deutsch.","why":"Do not combine bin with an ordinary present-tense verb."},{"id":"G01-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"ich + verb + information","model":"Ich lerne heute Deutsch.","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G01-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Du kommst aus Portugal.","model":"Example starting point: Sind Sie Frau Richter?","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":2,"level":"A1.1","title":"W-questions and verb position","goal":"Ask where, who, what and how, and build correct statements.","formula":"W-word + verb + person + rest?","explanations":["For a W-question, put the question word first and the conjugated verb immediately after it.","In statements the conjugated verb takes position two; position one may be a whole phrase, not just one word."],"notes":["Question words carry meaning: wer for people, wo for a location, woher for origin, wann for time.","Compare Wo wohnst du? (location) with Woher kommst du? (origin).","Even long first elements count as ONE slot before a conjugated verb.","The form of the verb still matches its subject after inversion."],"examples":[{"de":"Wo lernst du Deutsch?","en":"Where are you learning German?"},{"de":"Wie schreibt man deinen Namen?","en":"How does one write your name?"},{"de":"In Augsburg wohnt mein Freund.","en":"My friend lives in Augsburg."}],"trap":{"wrong":"Wo du wohnst?","correct":"Wo wohnst du?","why":"In a direct W-question, the finite verb follows the question word."},"challenge":"Ask a partner their name, home town and native language. Say one answer starting with a place.","questions":[{"id":"G02-01","step":2,"kind":"mc","prompt":"___ wohnst du?","answer":"Wo","explanation":"Wo asks for location.","options":["Wo","Wie","Wer"]},{"id":"G02-02","step":2,"kind":"mc","prompt":"Woher ___ deine Eltern?","answer":"kommen","explanation":"Plural parents require kommen.","options":["kommen","kommt","kommst"]},{"id":"G02-03","step":2,"kind":"mc","prompt":"Wann ___ der Kurs?","answer":"beginnt","explanation":"Kurs is singular.","options":["beginnt","beginnen","beginnst"]},{"id":"G02-04","step":2,"kind":"mc","prompt":"In Berlin ___ meine Cousine.","answer":"wohnt","explanation":"The verb comes second after the place.","options":["wohnt","wohnen","wohnst"]},{"id":"G02-05","step":2,"kind":"mc","prompt":"___ ist das? Das ist Timo.","answer":"Wer","explanation":"Wer asks who.","options":["Wer","Wo","Wann"]},{"id":"G02-06","step":2,"kind":"mc","prompt":"Wie ___ man das?","answer":"schreibt","explanation":"man takes third-person singular.","options":["schreibt","schreiben","schreibst"]},{"id":"G02-F1","step":2,"kind":"fill","prompt":"___ kommst du? (origin)","answer":"Woher","explanation":"Woher asks about origin."},{"id":"G02-F2","step":2,"kind":"fill","prompt":"In München ___ sie. (wohnen)","answer":"wohnt","explanation":"After the place the verb comes second. sie = she → wohnt; sie = they → wohnen. Both are correct.","accept":["wohnen"],"corrected":true}],"tasks":[{"id":"G02-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Wo du wohnst?","model":"Wo wohnst du?","why":"In a direct W-question, the finite verb follows the question word."},{"id":"G02-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"W-word + verb + person + rest?","model":"Wo lernst du Deutsch?","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G02-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Wie schreibt man deinen Namen?","model":"Example starting point: In Augsburg wohnt mein Freund.","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":3,"level":"A1.1","title":"Present tense, haben and nicht","goal":"Use all six persons and negate statements accurately.","formula":"subject + finite verb + nicht + relevant information","explanations":["Common endings: -e, -st, -t, -en, -t, -en. After stems ending -t or -d, du and er forms often need an extra -e-.","Use haben for possession and nicht for negating verbs, adjectives or phrases. Position of nicht depends on what is negated."],"notes":["Verb endings follow person, not the number of people physically present in a scene.","Learn sein and haben separately: bin/bist/ist and habe/hast/hat.","Negating an adjective differs from negating an unspecified noun: nicht teuer but kein Geld.","Introduce a number by reading it, then saying it within a full sentence."],"examples":[{"de":"Wir arbeiten am Freitag.","en":"We work on Friday."},{"de":"Ihr habt heute Unterricht.","en":"You all have class today."},{"de":"Sie wohnt nicht in Bonn.","en":"She does not live in Bonn."}],"trap":{"wrong":"Ihr arbeitst am Samstag.","correct":"Ihr arbeitet am Samstag.","why":"arbeiten requires arbeitet with ihr."},"challenge":"Describe your class with wir and ihr; add two negative statements about today.","questions":[{"id":"G03-01","step":3,"kind":"mc","prompt":"Wir ___ heute früh.","answer":"arbeiten","explanation":"wir takes the plural ending.","options":["arbeiten","arbeitet","arbeitest"]},{"id":"G03-02","step":3,"kind":"mc","prompt":"Ihr ___ zwei Kinder.","answer":"habt","explanation":"ihr has habt.","options":["habt","haben","hat"]},{"id":"G03-03","step":3,"kind":"mc","prompt":"Der Film ___ nicht interessant.","answer":"ist","explanation":"Singular Film uses ist.","options":["ist","sind","bin"]},{"id":"G03-04","step":3,"kind":"mc","prompt":"Du ___ heute keine Zeit.","answer":"hast","explanation":"du hast is irregular.","options":["hast","haben","hat"]},{"id":"G03-05","step":3,"kind":"mc","prompt":"Ihr ___ schon hier.","answer":"seid","explanation":"The ihr form of sein is seid.","options":["seid","sind","ist"]},{"id":"G03-06","step":3,"kind":"mc","prompt":"Du ___ in der Schule.","answer":"arbeitest","explanation":"arbeiten inserts e before -st.","options":["arbeitest","arbeits","arbeitet"]},{"id":"G03-F1","step":3,"kind":"fill","prompt":"Ihr ___ am Montag. (arbeiten)","answer":"arbeitet","explanation":"The ihr form is arbeitet."},{"id":"G03-F2","step":3,"kind":"fill","prompt":"Wir ___ müde. (sein)","answer":"sind","explanation":"wir sind is irregular."}],"tasks":[{"id":"G03-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Ihr arbeitst am Samstag.","model":"Ihr arbeitet am Samstag.","why":"arbeiten requires arbeitet with ihr."},{"id":"G03-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"subject + finite verb + nicht + relevant information","model":"Wir arbeiten am Freitag.","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G03-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Ihr habt heute Unterricht.","model":"Example starting point: Sie wohnt nicht in Bonn.","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":4,"level":"A1.1","title":"Yes/no questions and possession","goal":"Ask yes/no questions and answer negative questions with doch.","formula":"finite verb + subject + rest?","explanations":["Move the conjugated verb to the first position in a yes/no question. Do not use English-style do.","Use doch to contradict a negative question. Use mein/meine and dein/deine with grammatical gender and number."],"notes":["A simple statement becomes a neutral question when the finite verb moves first.","Ja confirms a positive question; nein rejects it; doch contradicts a negative proposition.","Possessive article endings follow grammatical gender, not who owns the object.","If unsure how to answer, repeat the verb in a complete sentence."],"examples":[{"de":"Hast du einen Bruder?","en":"Do you have a brother?"},{"de":"Wohnst du nicht hier? Doch, ich wohne hier.","en":"Don't you live here? Yes, I do."},{"de":"Das ist meine Schwester.","en":"This is my sister."}],"trap":{"wrong":"Du hast Geschwister?","correct":"Hast du Geschwister?","why":"For a neutral yes/no question, begin with the verb."},"challenge":"Make three yes/no questions, including one negative question that you answer with doch.","questions":[{"id":"G04-01","step":4,"kind":"mc","prompt":"___ du aus Österreich?","answer":"Kommst","explanation":"Begin yes/no questions with the finite verb.","options":["Kommst","Kommen","Kommt"]},{"id":"G04-02","step":4,"kind":"mc","prompt":"Du wohnst nicht hier? ___, ich wohne hier!","answer":"Doch","explanation":"Doch contradicts a negative question.","options":["Doch","Nein","Nie"]},{"id":"G04-03","step":4,"kind":"mc","prompt":"Das ist ___ Mutter.","answer":"meine","explanation":"Mutter is feminine nominative.","options":["meine","mein","meinen"]},{"id":"G04-04","step":4,"kind":"mc","prompt":"___ ihr Geschwister?","answer":"Habt","explanation":"ihr uses habt.","options":["Habt","Haben","Hat"]},{"id":"G04-05","step":4,"kind":"mc","prompt":"Das ist ___ Vater.","answer":"mein","explanation":"Vater is masculine nominative.","options":["mein","meine","meinen"]},{"id":"G04-06","step":4,"kind":"mc","prompt":"___ Anna verheiratet?","answer":"Ist","explanation":"Anna is one person (sie, singular): Ist Anna verheiratet?","options":["Ist","Hat","Sind"],"corrected":true},{"id":"G04-F1","step":4,"kind":"fill","prompt":"___ du heute frei? (haben)","answer":"Hast","explanation":"Question: finite verb first."},{"id":"G04-F2","step":4,"kind":"fill","prompt":"Das ist ___ Tante. (my)","answer":"meine","explanation":"Tante is feminine nominative."}],"tasks":[{"id":"G04-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Du hast Geschwister?","model":"Hast du Geschwister?","why":"For a neutral yes/no question, begin with the verb."},{"id":"G04-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"finite verb + subject + rest?","model":"Hast du einen Bruder?","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G04-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Wohnst du nicht hier? Doch, ich wohne hier.","model":"Example starting point: Das ist meine Schwester.","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":5,"level":"A1.1","title":"Noun gender and pronouns","goal":"Use der, das, die and the matching subject pronouns.","formula":"article + noun -> er / es / sie","explanations":["Every German noun has grammatical gender. Learn the noun with its article, not alone.","Replace a named object by er (der), es (das) or sie (die); all plural nouns use sie."],"notes":["Article and pronoun are a pair: der/er; das/es; die/sie.","Plural nouns all use die as definite article, regardless of singular gender.","The noun's gender is a grammar feature: do not infer it from an object's natural sex.","Adjectives after sein usually have no gender ending: Der Stuhl ist klein."],"examples":[{"de":"Der Rucksack ist schwer. Er ist voll.","en":"The backpack is heavy. It is full."},{"de":"Das Fenster ist offen. Es ist groß.","en":"The window is open. It is large."},{"de":"Die Brille ist neu. Sie ist schön.","en":"The glasses are new. They are nice."}],"trap":{"wrong":"Das Auto ist alt. Er ist kaputt.","correct":"Das Auto ist alt. Es ist kaputt.","why":"Auto is neuter: das -> es."},"challenge":"Look around you. Name six objects with articles; replace each with the right pronoun.","questions":[{"id":"G05-01","step":5,"kind":"mc","prompt":"___ Pullover ist warm.","answer":"Der","explanation":"Pullover is masculine.","options":["Der","Das","Die"]},{"id":"G05-02","step":5,"kind":"mc","prompt":"___ Kleid ist rot.","answer":"Das","explanation":"Kleid is neuter.","options":["Das","Der","Die"]},{"id":"G05-03","step":5,"kind":"mc","prompt":"___ Tasche ist groß.","answer":"Die","explanation":"Tasche is feminine.","options":["Die","Der","Das"]},{"id":"G05-04","step":5,"kind":"mc","prompt":"Das Fahrrad ist neu. ___ ist schnell.","answer":"Es","explanation":"das -> es.","options":["Es","Er","Sie"]},{"id":"G05-05","step":5,"kind":"mc","prompt":"Der Baum ist alt. ___ ist hoch.","answer":"Er","explanation":"der -> er.","options":["Er","Es","Sie"]},{"id":"G05-06","step":5,"kind":"mc","prompt":"Die Uhr ist kaputt. ___ geht nicht.","answer":"Sie","explanation":"die -> sie.","options":["Sie","Es","Er"]},{"id":"G05-F1","step":5,"kind":"fill","prompt":"Der Fernseher ist groß. ___ ist modern.","answer":"Er","explanation":"der -> er."},{"id":"G05-F2","step":5,"kind":"fill","prompt":"Das Zimmer ist klein. ___ ist hell.","answer":"Es","explanation":"das -> es."}],"tasks":[{"id":"G05-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Das Auto ist alt. Er ist kaputt.","model":"Das Auto ist alt. Es ist kaputt.","why":"Auto is neuter: das -> es."},{"id":"G05-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"article + noun -> er / es / sie","model":"Der Rucksack ist schwer. Er ist voll.","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G05-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Das Fenster ist offen. Es ist groß.","model":"Example starting point: Die Brille ist neu. Sie ist schön.","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":6,"level":"A1.1","title":"ein, eine, kein and nicht","goal":"Distinguish an indefinite noun from a negated noun or adjective.","formula":"Das ist + ein/eine/kein/keine + noun","explanations":["Use ein for masculine and neuter nominative nouns; eine for feminine nouns. Kein follows similar endings and can negate plural nouns.","Use nicht for adjective, verb and specific-phrase negation: nicht teuer, nicht hier, nicht der Schlüssel."],"notes":["First mention an object with ein/eine; refer to the specific known object with der/die/das.","Kein replaces ein or negates a noun without an article, including a plural noun.","Nicht denies properties, verbs, locations and specific noun phrases.","In the accusative case some ein/kein forms change; see Step 7."],"examples":[{"de":"Das ist ein Kalender.","en":"That is a calendar."},{"de":"Wir haben keine Milch.","en":"We have no milk."},{"de":"Der Laptop ist nicht teuer.","en":"The laptop is not expensive."}],"trap":{"wrong":"Das ist nicht Computer.","correct":"Das ist kein Computer.","why":"Negating an indefinite count noun normally requires kein."},"challenge":"Describe five household items, including two things you do not have.","questions":[{"id":"G06-01","step":6,"kind":"mc","prompt":"Das ist ___ Lampe.","answer":"eine","explanation":"Feminine nominative takes eine.","options":["eine","ein","einen"]},{"id":"G06-02","step":6,"kind":"mc","prompt":"Wir haben ___ Zucker.","answer":"keinen","explanation":"Zucker is masculine accusative.","options":["keinen","kein","keine"]},{"id":"G06-03","step":6,"kind":"mc","prompt":"Die Musik ist ___ laut.","answer":"nicht","explanation":"Negate an adjective with nicht.","options":["nicht","kein","keine"]},{"id":"G06-04","step":6,"kind":"mc","prompt":"Das ist ___ Schlüssel.","answer":"ein","explanation":"Masculine nominative takes ein.","options":["ein","eine","einen"]},{"id":"G06-05","step":6,"kind":"mc","prompt":"Ich habe ___ Kinder.","answer":"keine","explanation":"Plural absence takes keine.","options":["keine","kein","nicht"]},{"id":"G06-06","step":6,"kind":"mc","prompt":"Das ist ___ mein Mantel.","answer":"nicht","explanation":"A specific possessive phrase is negated with nicht.","options":["nicht","kein","keine"]},{"id":"G06-F1","step":6,"kind":"fill","prompt":"Das ist ___ Uhr. (a)","answer":"eine","explanation":"Feminine nominative takes eine."},{"id":"G06-F2","step":6,"kind":"fill","prompt":"Ich habe ___ Hunger. (no)","answer":"keinen","explanation":"Hunger is masculine accusative."}],"tasks":[{"id":"G06-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Das ist nicht Computer.","model":"Das ist kein Computer.","why":"Negating an indefinite count noun normally requires kein."},{"id":"G06-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"Das ist + ein/eine/kein/keine + noun","model":"Das ist ein Kalender.","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G06-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Wir haben keine Milch.","model":"Example starting point: Der Laptop ist nicht teuer.","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":7,"level":"A1.1","title":"Plurals and accusative","goal":"Use plural nouns and change masculine objects into den/einen.","formula":"subject + verb + einen/den + masculine object","explanations":["Learn plural forms with each noun; endings can be -e, -en, -er, -s or zero.","In the accusative, masculine articles change: der->den, ein->einen, kein->keinen. Feminine and neuter articles generally stay the same."],"notes":["Ask who performs the action (nominative) and what receives it (accusative).","Only masculine singular definite/indefinite articles visibly change in this simple case comparison.","Many feminine nouns make plural with -(e)n, but don't rely on guesses for every noun.","Keep a vocabulary record: article + singular + plural + a model sentence."],"examples":[{"de":"Ich brauche einen Regenschirm.","en":"I need an umbrella."},{"de":"Wir kaufen die Bücher.","en":"We are buying the books."},{"de":"Kennst du den Lehrer?","en":"Do you know the teacher?"}],"trap":{"wrong":"Ich sehe ein Mann.","correct":"Ich sehe einen Mann.","why":"A masculine accusative object needs einen."},"challenge":"Write a shopping list with six nouns and say three full sentences about what you need.","questions":[{"id":"G07-01","step":7,"kind":"mc","prompt":"Ich suche ___ Bahnhof.","answer":"den","explanation":"Masculine accusative: den.","options":["den","der","dem"]},{"id":"G07-02","step":7,"kind":"mc","prompt":"Wir brauchen ___ Tisch.","answer":"einen","explanation":"Masculine accusative: einen.","options":["einen","ein","einem"]},{"id":"G07-03","step":7,"kind":"mc","prompt":"Ich kaufe ___ Tasche.","answer":"eine","explanation":"Tasche is feminine.","options":["eine","einen","ein"]},{"id":"G07-04","step":7,"kind":"mc","prompt":"das Kind -> die ___","answer":"Kinder","explanation":"Kind has plural Kinder.","options":["Kinder","Kinds","Kinden"]},{"id":"G07-05","step":7,"kind":"mc","prompt":"die Zeitung -> die ___","answer":"Zeitungen","explanation":"Feminine -ung nouns usually pluralize with -en.","options":["Zeitungen","Zeitunges","Zeitunger"]},{"id":"G07-06","step":7,"kind":"mc","prompt":"Er nimmt ___ Apfel.","answer":"einen","explanation":"Apfel is masculine accusative.","options":["einen","ein","einem"]},{"id":"G07-F1","step":7,"kind":"fill","prompt":"Wir nehmen ___ Bus. (the)","answer":"den","explanation":"Masculine accusative article den."},{"id":"G07-F2","step":7,"kind":"fill","prompt":"Ein Buch, zwei ___.","answer":"Bücher","explanation":"Plural is Bücher."}],"tasks":[{"id":"G07-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Ich sehe ein Mann.","model":"Ich sehe einen Mann.","why":"A masculine accusative object needs einen."},{"id":"G07-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"subject + verb + einen/den + masculine object","model":"Ich brauche einen Regenschirm.","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G07-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Wir kaufen die Bücher.","model":"Example starting point: Kennst du den Lehrer?","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":8,"level":"A1.1","title":"können and sentence bracket","goal":"Say what you can do and keep the second verb at the end.","formula":"subject + können + details + infinitive","explanations":["Modal verbs such as können occupy the conjugated verb position; the full verb appears as infinitive at the end.","Some strong verbs change vowels with du and er/sie/es (fahren->fährst, lesen->liest)."],"notes":["A conjugated modal and a final infinitive form a sentence bracket.","If you start with time, the modal still stays second: Heute kann ich kommen.","Strong vowel change is limited to some verbs and mostly du and er/sie/es.","Compare können (ability) with dürfen (permission), learned later."],"examples":[{"de":"Ich kann am Abend kochen.","en":"I can cook in the evening."},{"de":"Kannst du gut schwimmen?","en":"Can you swim well?"},{"de":"Mein Bruder fährt jeden Tag Rad.","en":"My brother cycles every day."}],"trap":{"wrong":"Sie kann spricht Deutsch.","correct":"Sie kann Deutsch sprechen.","why":"After a modal, use the infinitive at the end."},"challenge":"Say three things you can do, two things you cannot do and one question to a classmate.","questions":[{"id":"G08-01","step":8,"kind":"mc","prompt":"Ich ___ heute nicht kommen.","answer":"kann","explanation":"ich kann is irregular.","options":["kann","könne","kannst"]},{"id":"G08-02","step":8,"kind":"mc","prompt":"Kannst du heute ___?","answer":"lernen","explanation":"The main verb remains infinitive.","options":["lernen","lernst","gelernt"]},{"id":"G08-03","step":8,"kind":"mc","prompt":"Meine Schwester ___ sehr gut singen.","answer":"kann","explanation":"Meine Schwester = sie (singular) → kann.","options":["kann","können","kannst"],"corrected":true},{"id":"G08-04","step":8,"kind":"mc","prompt":"Du ___ gern Bücher.","answer":"liest","explanation":"lesen changes e->ie with du.","options":["liest","lest","lesen"]},{"id":"G08-05","step":8,"kind":"mc","prompt":"Mein Vater ___ oft nach Ulm.","answer":"fährt","explanation":"fahren changes a->ä in er.","options":["fährt","fahrt","fahre"]},{"id":"G08-06","step":8,"kind":"mc","prompt":"Ich kann meine Freundin ___.","answer":"besuchen","explanation":"After kann, use infinitive at sentence end.","options":["besuchen","besuche","besucht"]},{"id":"G08-F1","step":8,"kind":"fill","prompt":"Ich ___ gut zeichnen. (can)","answer":"kann","explanation":"ich kann."},{"id":"G08-F2","step":8,"kind":"fill","prompt":"Sie kann nicht ___. (kommen)","answer":"kommen","explanation":"The second verb remains infinitive."}],"tasks":[{"id":"G08-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Sie kann spricht Deutsch.","model":"Sie kann Deutsch sprechen.","why":"After a modal, use the infinitive at the end."},{"id":"G08-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"subject + können + details + infinitive","model":"Ich kann am Abend kochen.","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G08-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Kannst du gut schwimmen?","model":"Example starting point: Mein Bruder fährt jeden Tag Rad.","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":9,"level":"A1.1","title":"Time phrases and word order","goal":"Begin sentences with time and say when events happen.","formula":"time phrase + finite verb + subject + rest","explanations":["When a time expression begins a statement, the conjugated verb still comes second: Morgen komme ich.","Use am for days and parts of days; um for clock times. halb acht = 7:30."],"notes":["German's halb refers to the coming hour: halb vier is 3:30.","Use um with a specific clock time, not with a weekday.","A time phrase at the start pushes the subject behind the finite verb.","For dates and months use different expressions; don't treat all time words alike."],"examples":[{"de":"Am Dienstag habe ich Unterricht.","en":"I have class on Tuesday."},{"de":"Um halb acht beginnt mein Kurs.","en":"My class starts at half past seven."},{"de":"Heute Abend komme ich später.","en":"I'll arrive later this evening."}],"trap":{"wrong":"Morgen ich arbeite.","correct":"Morgen arbeite ich.","why":"Time is first; the conjugated verb must remain second."},"challenge":"Explain your schedule for three days and give precise times.","questions":[{"id":"G09-01","step":9,"kind":"mc","prompt":"___ Montag habe ich frei.","answer":"Am","explanation":"Days take am.","options":["Am","Um","Im"]},{"id":"G09-02","step":9,"kind":"mc","prompt":"___ 15 Uhr beginnt der Kurs.","answer":"Um","explanation":"Clock time takes um.","options":["Um","Am","Ab"]},{"id":"G09-03","step":9,"kind":"mc","prompt":"Es ist halb neun = ___.","answer":"08:30","explanation":"halb neun means half toward nine.","options":["08:30","09:30","08:15"]},{"id":"G09-04","step":9,"kind":"mc","prompt":"Heute ___ wir im Büro.","answer":"arbeiten","explanation":"Verb is second after Heute.","options":["arbeiten","wir arbeiten","arbeitet"]},{"id":"G09-05","step":9,"kind":"mc","prompt":"Morgen ___ ich um sieben auf.","answer":"stehe","explanation":"The verb takes the second position.","options":["stehe","ich stehe","steht"]},{"id":"G09-06","step":9,"kind":"mc","prompt":"Am Abend ___ Lea Klavier.","answer":"spielt","explanation":"Lea = sie (singular) takes -t: spielt. The verb is second after Am Abend.","options":["spielt","spielen","spielst"],"corrected":true},{"id":"G09-F1","step":9,"kind":"fill","prompt":"___ Samstag lerne ich. (on)","answer":"Am","explanation":"Days use am."},{"id":"G09-F2","step":9,"kind":"fill","prompt":"Der Film beginnt ___ 19 Uhr.","answer":"um","explanation":"Clock time uses um."}],"tasks":[{"id":"G09-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Morgen ich arbeite.","model":"Morgen arbeite ich.","why":"Time is first; the conjugated verb must remain second."},{"id":"G09-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"time phrase + finite verb + subject + rest","model":"Am Dienstag habe ich Unterricht.","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G09-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Um halb acht beginnt mein Kurs.","model":"Example starting point: Heute Abend komme ich später.","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":10,"level":"A1.1","title":"mögen, möchte and ordering","goal":"Express likes, polite wishes and food choices.","formula":"ich möchte + accusative object + bitte","explanations":["mögen describes preference; möchte is a polite wish or request. Essen and nehmen have irregular du/er forms.","The food or drink is commonly a direct object, so masculine nouns often need einen or den."],"notes":["Use mögen for lasting tastes; möchte is useful for a polite request now.","Memorize the natural chunk Ich hätte gern later; for now Ich möchte is enough.","Masculine direct objects often require einen, even for drinks.","Compound nouns inherit gender from the final noun: der Saft -> der Orangensaft."],"examples":[{"de":"Ich mag scharfe Suppe.","en":"I like spicy soup."},{"de":"Ich möchte einen Apfelsaft, bitte.","en":"I'd like an apple juice, please."},{"de":"Was nimmst du? Ich nehme einen Salat.","en":"What will you have? I'll take a salad."}],"trap":{"wrong":"Ich möchte ein Kaffee.","correct":"Ich möchte einen Kaffee.","why":"Kaffee is masculine and an accusative object."},"challenge":"Order three things politely, then explain one thing you do not like.","questions":[{"id":"G10-01","step":10,"kind":"mc","prompt":"Ich ___ Käse, aber keine Butter.","answer":"mag","explanation":"ich mag (no ending) – mögen describes a general preference.","options":["mag","magst","mögen"],"corrected":true},{"id":"G10-02","step":10,"kind":"mc","prompt":"Ich ___ bitte ein Wasser.","answer":"möchte","explanation":"möchte expresses a polite request.","options":["möchte","magst","mögen"]},{"id":"G10-03","step":10,"kind":"mc","prompt":"Du ___ gern Reis.","answer":"isst","explanation":"essen changes e->i with du.","options":["isst","esst","esse"]},{"id":"G10-04","step":10,"kind":"mc","prompt":"Wir ___ zwei Suppen.","answer":"nehmen","explanation":"wir takes nehmen.","options":["nehmen","nimmt","nehmt"]},{"id":"G10-05","step":10,"kind":"mc","prompt":"Ich bestelle ___ Tee.","answer":"einen","explanation":"Tee is masculine accusative.","options":["einen","ein","einem"]},{"id":"G10-06","step":10,"kind":"mc","prompt":"___ Sie etwas trinken?","answer":"Möchten","explanation":"Polite Sie uses möchten.","options":["Möchten","Möchtest","Magst"]},{"id":"G10-F1","step":10,"kind":"fill","prompt":"Ich ___ einen Tee, bitte. (would like)","answer":"möchte","explanation":"A polite request uses möchte."},{"id":"G10-F2","step":10,"kind":"fill","prompt":"Er ___ gern Brot. (eat)","answer":"isst","explanation":"essen changes in er."}],"tasks":[{"id":"G10-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Ich möchte ein Kaffee.","model":"Ich möchte einen Kaffee.","why":"Kaffee is masculine and an accusative object."},{"id":"G10-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"ich möchte + accusative object + bitte","model":"Ich möchte einen Apfelsaft, bitte.","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G10-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Ich möchte einen Apfelsaft, bitte.","model":"Example starting point: Was nimmst du? Ich nehme einen Salat.","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":11,"level":"A1.1","title":"Separable verbs","goal":"Build sentences with separable verb prefixes and recognize infinitives.","formula":"subject + conjugated verb + ... + prefix","explanations":["With separable verbs, the conjugated stem appears in position two and the prefix moves to the end of a main clause.","With a modal verb the entire infinitive stays together at the end: Ich muss früh aufstehen."],"notes":["The detachable prefix may move to the very end after objects and time phrases.","Modal + separable infinitive stays together: Ich kann jetzt aufstehen.","In a direct yes/no question the finite stem comes first and the prefix last.","Keep accents on the prefix when speaking (AUFstehen); it helps recognition."],"examples":[{"de":"Um sieben Uhr stehe ich auf.","en":"I get up at seven."},{"de":"Der Bus fährt um acht Uhr ab.","en":"The bus departs at eight."},{"de":"Ich kann dich später anrufen.","en":"I can call you later."}],"trap":{"wrong":"Ich aufstehe um sechs Uhr.","correct":"Ich stehe um sechs Uhr auf.","why":"The prefix of aufstehen separates in this main clause."},"challenge":"Describe your morning with four separable verbs and one modal sentence.","questions":[{"id":"G11-01","step":11,"kind":"mc","prompt":"Morgen ___ ich früh ___.","answer":"stehe ... auf","explanation":"aufstehen separates in a simple main clause.","options":["stehe ... auf","aufstehe ... (nothing)","stehen ... auf"]},{"id":"G11-02","step":11,"kind":"mc","prompt":"Der Zug ___ um 9 Uhr ___.","answer":"fährt ... ab","explanation":"abfahren separates in a main clause.","options":["fährt ... ab","abfährt ... (nothing)","fahrt ... ab"]},{"id":"G11-03","step":11,"kind":"mc","prompt":"Ich kann dich morgen ___.","answer":"anrufen","explanation":"After kann use intact infinitive.","options":["anrufen","rufe an","angerufen"]},{"id":"G11-04","step":11,"kind":"mc","prompt":"Wann ___ der Bus ___?","answer":"kommt ... an","explanation":"ankommen separates in direct questions.","options":["kommt ... an","ankommt ... (nothing)","kommen ... an"]},{"id":"G11-05","step":11,"kind":"mc","prompt":"Wir ___ am Wochenende ___.","answer":"kaufen ... ein","explanation":"Wir kaufen ... ein.","options":["kaufen ... ein","einkaufen ... (nothing)","kauft ... ein"]},{"id":"G11-06","step":11,"kind":"mc","prompt":"Du ___ die Tür ___.","answer":"machst ... zu","explanation":"The prefix zu separates in present-tense main clauses.","options":["machst ... zu","zumachst ... (nothing)","machen ... zu"]},{"id":"G11-F1","step":11,"kind":"fill","prompt":"Ich rufe dich heute Abend ___. (call)","answer":"an","explanation":"The prefix an goes to the end."},{"id":"G11-F2","step":11,"kind":"fill","prompt":"Morgen ___ der Zug an. (arrive)","answer":"kommt","explanation":"The conjugated stem of ankommen is kommt."}],"tasks":[{"id":"G11-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Ich aufstehe um sechs Uhr.","model":"Ich stehe um sechs Uhr auf.","why":"The prefix of aufstehen separates in this main clause."},{"id":"G11-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"subject + conjugated verb + ... + prefix","model":"Um sieben Uhr stehe ich auf.","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G11-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Der Bus fährt um acht Uhr ab.","model":"Example starting point: Ich kann dich später anrufen.","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":12,"level":"A1.1","title":"Perfekt with haben","goal":"Talk about completed actions with haben and a participle.","formula":"subject + haben + time/object + Partizip II","explanations":["For many past events, use the present tense of haben plus the past participle at sentence end.","Regular participles often use ge-...-t; many irregular verbs use -en. Verbs ending -ieren form participles without ge-."],"notes":["Perfekt has two parts: auxiliary verb and past participle, separated in a main clause.","Some common irregular participles have vowel changes; learn them as vocabulary.","Separable verbs insert ge- after the prefix: aufgeräumt, angerufen.","-ieren verbs never add ge-: organisiert, repariert."],"examples":[{"de":"Ich habe gestern gekocht.","en":"I cooked yesterday."},{"de":"Wir haben einen Film gesehen.","en":"We watched a film."},{"de":"Hast du heute telefoniert?","en":"Did you make a phone call today?"}],"trap":{"wrong":"Ich habe gestern einkaufen.","correct":"Ich habe gestern eingekauft.","why":"A completed past action requires the participle."},"challenge":"Tell a partner what you did yesterday using at least five different participles.","questions":[{"id":"G12-01","step":12,"kind":"mc","prompt":"Ich ___ gestern Brot gekauft.","answer":"habe","explanation":"kaufen uses Perfekt with haben.","options":["habe","bin","hat"]},{"id":"G12-02","step":12,"kind":"mc","prompt":"Wir haben Musik ___.","answer":"gehört","explanation":"The participle of hören is gehört.","options":["gehört","hören","gehören"]},{"id":"G12-03","step":12,"kind":"mc","prompt":"Du ___ deine Schwester angerufen.","answer":"hast","explanation":"Anrufen uses haben with du hast.","options":["hast","bist","hat"]},{"id":"G12-04","step":12,"kind":"mc","prompt":"Er hat heute ___.","answer":"telefoniert","explanation":"Verbs in -ieren form participles without ge-.","options":["telefoniert","getelefoniert","telefonieren"]},{"id":"G12-05","step":12,"kind":"mc","prompt":"Wir ___ einen Ausflug gemacht.","answer":"haben","explanation":"machen normally takes haben.","options":["haben","sind","hat"]},{"id":"G12-06","step":12,"kind":"mc","prompt":"Was hast du gestern ___?","answer":"gelesen","explanation":"lesen has irregular participle gelesen.","options":["gelesen","lesen","geliest"]},{"id":"G12-F1","step":12,"kind":"fill","prompt":"Wir haben gestern ___. (cook)","answer":"gekocht","explanation":"kochen -> gekocht."},{"id":"G12-F2","step":12,"kind":"fill","prompt":"Sie hat Musik ___. (hear)","answer":"gehört","explanation":"hören -> gehört."}],"tasks":[{"id":"G12-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Ich habe gestern einkaufen.","model":"Ich habe gestern eingekauft.","why":"A completed past action requires the participle."},{"id":"G12-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"subject + haben + time/object + Partizip II","model":"Ich habe gestern gekocht.","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G12-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Wir haben einen Film gesehen.","model":"Example starting point: Hast du heute telefoniert?","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":13,"level":"A1.1","title":"Perfekt with sein and past states","goal":"Choose sein for many movement/change verbs and use war/hatte.","formula":"subject + bin/ist/sind + ... + Partizip II","explanations":["Many intransitive movement and change-of-state verbs form Perfekt with sein; bleiben also uses sein.","For sein and haben themselves, everyday German often uses war and hatte for the past."],"notes":["Compare an action (ich bin gefahren) with a past state (ich war müde).","Not every verb about movement takes sein in every context; learn common A1 patterns first.","The participle still goes last when sein is the auxiliary.","Since the event may involve several verbs, choose auxiliary for each separately."],"examples":[{"de":"Ich bin spät angekommen.","en":"I arrived late."},{"de":"Wir sind am Sonntag gewandert.","en":"We hiked on Sunday."},{"de":"Letzte Woche hatte ich Urlaub.","en":"I had vacation last week."}],"trap":{"wrong":"Wir haben nach Hause gegangen.","correct":"Wir sind nach Hause gegangen.","why":"gehen forms Perfekt with sein."},"challenge":"Tell a short story: where you went, what you did and how the day was.","questions":[{"id":"G13-01","step":13,"kind":"mc","prompt":"Ich ___ nach Hause gegangen.","answer":"bin","explanation":"gehen forms Perfekt with sein.","options":["bin","habe","hat"]},{"id":"G13-02","step":13,"kind":"mc","prompt":"Wir ___ spät angekommen.","answer":"sind","explanation":"ankommen takes sein.","options":["sind","haben","seid"]},{"id":"G13-03","step":13,"kind":"mc","prompt":"Gestern ___ ich sehr müde.","answer":"war","explanation":"The past of sein is war.","options":["war","hatte","bin"]},{"id":"G13-04","step":13,"kind":"mc","prompt":"Letztes Jahr ___ ich wenig Zeit.","answer":"hatte","explanation":"The past of haben is hatte.","options":["hatte","war","habe"]},{"id":"G13-05","step":13,"kind":"mc","prompt":"Sie ___ in Hamburg geblieben.","answer":"ist","explanation":"bleiben takes sein.","options":["ist","hat","haben"]},{"id":"G13-06","step":13,"kind":"mc","prompt":"Wann ___ du aufgestanden?","answer":"bist","explanation":"aufstehen takes sein.","options":["bist","hast","ist"]},{"id":"G13-F1","step":13,"kind":"fill","prompt":"Ich ___ früh aufgestanden.","answer":"bin","explanation":"aufstehen uses sein."},{"id":"G13-F2","step":13,"kind":"fill","prompt":"Letztes Jahr ___ wir in Berlin. (were)","answer":"waren","explanation":"The past of sein for wir is waren."}],"tasks":[{"id":"G13-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Wir haben nach Hause gegangen.","model":"Wir sind nach Hause gegangen.","why":"gehen forms Perfekt with sein."},{"id":"G13-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"subject + bin/ist/sind + ... + Partizip II","model":"Ich bin spät angekommen.","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G13-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Wir sind am Sonntag gewandert.","model":"Example starting point: Letzte Woche hatte ich Urlaub.","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":14,"level":"A1.2","title":"es gibt and dative pronouns","goal":"Describe what exists and say what people like.","formula":"es gibt + accusative; es gefällt + dative person","explanations":["es gibt takes an accusative object even if the noun is plural.","Dative pronouns such as mir, dir, ihm, ihr express whom something pleases or to whom something is given."],"notes":["es gibt can be used with singular or plural objects, but the verb remains gibt.","Ask Was gibt es hier? then answer with an accusative noun phrase.","gefallen has a different structure from mögen: Das Haus gefällt mir.","With plural nouns the finite verb gefallen is plural, not gefällt."],"examples":[{"de":"In der Stadt gibt es einen Park.","en":"There is a park in town."},{"de":"Das Museum gefällt mir.","en":"I like the museum."},{"de":"Wie gefällt dir der Platz?","en":"How do you like the square?"}],"trap":{"wrong":"Mir gefällt die Cafés.","correct":"Mir gefallen die Cafés.","why":"A plural subject requires gefallen."},"challenge":"Describe two places in your town, saying what exists and what you like.","questions":[{"id":"G14-01","step":14,"kind":"mc","prompt":"Hier gibt es ___ Markt.","answer":"einen","explanation":"es gibt takes accusative.","options":["einen","ein","einem"]},{"id":"G14-02","step":14,"kind":"mc","prompt":"Das neue Café gefällt ___.","answer":"mir","explanation":"gefallen takes a dative person.","options":["mir","mich","ich"]},{"id":"G14-03","step":14,"kind":"mc","prompt":"Wie gefällt ___ die Schule?","answer":"dir","explanation":"gefallen takes the dative person: Wie gefällt dir …?","options":["dir","dich","du"],"corrected":true},{"id":"G14-04","step":14,"kind":"mc","prompt":"Die Bilder ___ mir gut.","answer":"gefallen","explanation":"Plural subject -> gefallen.","options":["gefallen","gefällt","gefallt"]},{"id":"G14-05","step":14,"kind":"mc","prompt":"Es ___ viele Geschäfte.","answer":"gibt","explanation":"es gibt is a fixed singular expression.","options":["gibt","geben","ist"]},{"id":"G14-06","step":14,"kind":"mc","prompt":"Der Lehrer hilft ___.","answer":"uns","explanation":"helfen takes dative; uns is dative plural.","options":["uns","wir","unser"]},{"id":"G14-F1","step":14,"kind":"fill","prompt":"Der Platz gefällt ___. (me)","answer":"mir","explanation":"gefallen takes dative."},{"id":"G14-F2","step":14,"kind":"fill","prompt":"Hier ___ es drei Hotels.","answer":"gibt","explanation":"es gibt is fixed."}],"tasks":[{"id":"G14-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Mir gefällt die Cafés.","model":"Mir gefallen die Cafés.","why":"A plural subject requires gefallen."},{"id":"G14-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"es gibt + accusative; es gefällt + dative person","model":"In der Stadt gibt es einen Park.","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G14-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Das Museum gefällt mir.","model":"Example starting point: Wie gefällt dir der Platz?","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":15,"level":"A1.2","title":"Dative articles and location","goal":"Use mit, zu, bei and wo? with dative articles.","formula":"mit + dem/der/den; in + dative location","explanations":["Dative articles are dem (masculine/neuter), der (feminine), den (plural). Plural nouns often add -n if possible.","After mit, bei, zu, aus and von, use dative. For static location with in, also use dative."],"notes":["Learn dative as the usual partner of mit, zu, bei, aus, von, nach and seit.","Remember masculine/neuter dem, feminine der, plural den (often with noun -n).","Wo? can use in + dative for a fixed location.","Do not automatically use dative after every in: direction needs accusative (Step 24)."],"examples":[{"de":"Ich fahre mit dem Zug.","en":"I travel by train."},{"de":"Sie wohnt bei ihrer Tante.","en":"She lives with her aunt."},{"de":"Wir sind in der Bibliothek.","en":"We are in the library."}],"trap":{"wrong":"Ich fahre mit die Bahn.","correct":"Ich fahre mit der Bahn.","why":"mit always requires dative."},"challenge":"Give directions to three places using mit, zu and in.","questions":[{"id":"G15-01","step":15,"kind":"mc","prompt":"Ich fahre mit ___ Taxi.","answer":"dem","explanation":"mit takes dative, Taxi is neuter.","options":["dem","das","den"]},{"id":"G15-02","step":15,"kind":"mc","prompt":"Er wohnt bei ___ Oma.","answer":"der","explanation":"bei + feminine dative: der.","options":["der","die","den"]},{"id":"G15-03","step":15,"kind":"mc","prompt":"Sie kommt aus ___ Schweiz.","answer":"der","explanation":"aus takes dative, die Schweiz -> der Schweiz.","options":["der","die","dem"]},{"id":"G15-04","step":15,"kind":"mc","prompt":"Wir helfen ___ Kindern.","answer":"den","explanation":"Plural dative uses den.","options":["den","die","der"]},{"id":"G15-05","step":15,"kind":"mc","prompt":"Ich bin in ___ Küche.","answer":"der","explanation":"Static position in a feminine place -> der.","options":["der","die","den"]},{"id":"G15-06","step":15,"kind":"mc","prompt":"Sie geht zu ___ Arzt.","answer":"dem","explanation":"zu takes dative, masculine dem.","options":["dem","den","der"]},{"id":"G15-F1","step":15,"kind":"fill","prompt":"Ich komme mit ___ Bus. (the)","answer":"dem","explanation":"mit + masculine dative."},{"id":"G15-F2","step":15,"kind":"fill","prompt":"Er hilft ___ Frau. (the)","answer":"der","explanation":"helfen takes dative."}],"tasks":[{"id":"G15-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Ich fahre mit die Bahn.","model":"Ich fahre mit der Bahn.","why":"mit always requires dative."},{"id":"G15-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"mit + dem/der/den; in + dative location","model":"Ich fahre mit dem Zug.","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G15-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Sie wohnt bei ihrer Tante.","model":"Example starting point: Wir sind in der Bibliothek.","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":16,"level":"A1.2","title":"Possessives in different cases","goal":"Choose possessive endings for gender and grammatical case.","formula":"mein/dein/sein/ihr/unser + matching ending + noun","explanations":["Possessive words take endings similar to ein. Their form depends on gender, number and case.","Nominative masculine: mein Bruder; accusative masculine: meinen Bruder; dative masculine: meinem Bruder."],"notes":["Possessives combine owner (mein, dein, sein, ihr, unser) with endings from gender and case.","Masculine accusative is easy to notice: mein Bruder -> meinen Bruder.","Dative masculine/neuter normally ends -em: meinem Vater, meinem Kind.","Plural and feminine forms look similar in some positions; always ask case and number."],"examples":[{"de":"Das ist unser Garten.","en":"This is our garden."},{"de":"Ich besuche meinen Onkel.","en":"I'm visiting my uncle."},{"de":"Sie hilft ihrer Mutter.","en":"She helps her mother."}],"trap":{"wrong":"Ich kenne mein Bruder.","correct":"Ich kenne meinen Bruder.","why":"kennen takes an accusative object."},"challenge":"Describe family, friends and belongings in five original sentences using different possessives.","questions":[{"id":"G16-01","step":16,"kind":"mc","prompt":"Ich besuche ___ Bruder.","answer":"meinen","explanation":"Masculine accusative uses meinen.","options":["meinen","mein","meinem"]},{"id":"G16-02","step":16,"kind":"mc","prompt":"Das ist ___ Wohnung.","answer":"unsere","explanation":"Feminine nominative takes unsere.","options":["unsere","unser","unseren"]},{"id":"G16-03","step":16,"kind":"mc","prompt":"Sie spricht mit ___ Vater.","answer":"ihrem","explanation":"mit + masculine dative needs ihrem.","options":["ihrem","ihren","ihr"]},{"id":"G16-04","step":16,"kind":"mc","prompt":"Wo ist ___ Auto?","answer":"dein","explanation":"Neuter nominative uses dein.","options":["dein","deine","deinen"]},{"id":"G16-05","step":16,"kind":"mc","prompt":"Er kennt ___ Schwester.","answer":"seine","explanation":"Feminine accusative uses seine.","options":["seine","sein","seinen"]},{"id":"G16-06","step":16,"kind":"mc","prompt":"Ich gebe ___ Kind ein Buch.","answer":"meinem","explanation":"dative neuter is meinem.","options":["meinem","mein","meinen"]},{"id":"G16-F1","step":16,"kind":"fill","prompt":"Ich sehe ___ Vater. (my)","answer":"meinen","explanation":"Accusative masculine possessive."},{"id":"G16-F2","step":16,"kind":"fill","prompt":"Wir helfen ___ Freund. (our)","answer":"unserem","explanation":"Dative masculine possessive."}],"tasks":[{"id":"G16-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Ich kenne mein Bruder.","model":"Ich kenne meinen Bruder.","why":"kennen takes an accusative object."},{"id":"G16-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"mein/dein/sein/ihr/unser + matching ending + noun","model":"Das ist unser Garten.","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G16-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Ich besuche meinen Onkel.","model":"Example starting point: Sie hilft ihrer Mutter.","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":17,"level":"A1.2","title":"Time prepositions and polite requests","goal":"Talk about time spans and ask politely with könnten.","formula":"in/vor/nach + time; Könnten Sie ... + infinitive?","explanations":["Use in zwei Stunden for a future time, vor zwei Tagen for time ago, and nach der Arbeit for after work.","For polite requests, könnten + Sie/du ... + infinitive at end. Learn the whole phrase; it is less direct than an imperative."],"notes":["in can point forward in time: in einer Stunde = one hour from now.","vor + dative time measures backward: vor zwei Tagen.","nach + dative marks a sequence: nach dem Mittagessen.","Könnten Sie ...? is a useful polite phrase; the second verb belongs at the end."],"examples":[{"de":"Ich komme in zehn Minuten.","en":"I'll come in ten minutes."},{"de":"Vor einer Woche war ich krank.","en":"I was ill a week ago."},{"de":"Könnten Sie mir bitte helfen?","en":"Could you help me, please?"}],"trap":{"wrong":"Könnten Sie mir bitte helfen machen?","correct":"Könnten Sie mir bitte helfen?","why":"Only the infinitive helfen is required at the end."},"challenge":"Ask for help twice: one informal request and one polite request to an official.","questions":[{"id":"G17-01","step":17,"kind":"mc","prompt":"Ich komme ___ fünf Minuten.","answer":"in","explanation":"in five minutes refers to future.","options":["in","vor","nach"]},{"id":"G17-02","step":17,"kind":"mc","prompt":"___ drei Tagen war Sonntag.","answer":"Vor","explanation":"Vor + time indicates time ago.","options":["Vor","In","Nach"]},{"id":"G17-03","step":17,"kind":"mc","prompt":"___ dem Unterricht gehen wir nach Hause.","answer":"Nach","explanation":"nach + dative indicates after.","options":["Nach","In","Vor"]},{"id":"G17-04","step":17,"kind":"mc","prompt":"___ Sie bitte langsamer sprechen?","answer":"Könnten","explanation":"Polite conditional request: Könnten Sie ...?","options":["Könnten","Könnt","Könnenst"]},{"id":"G17-05","step":17,"kind":"mc","prompt":"Ich fahre ___ einer Stunde los.","answer":"in","explanation":"Future duration: in einer Stunde.","options":["in","vor","bei"]},{"id":"G17-06","step":17,"kind":"mc","prompt":"___ du mir kurz helfen?","answer":"Könntest","explanation":"Informal polite question: Könntest du ...?","options":["Könntest","Könnten","Könnte"]},{"id":"G17-F1","step":17,"kind":"fill","prompt":"Ich komme ___ einer Stunde. (in)","answer":"in","explanation":"in einer Stunde = one hour from now."},{"id":"G17-F2","step":17,"kind":"fill","prompt":"___ Sie mir bitte helfen? (could)","answer":"Könnten","explanation":"Formal polite könnten."}],"tasks":[{"id":"G17-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Könnten Sie mir bitte helfen machen?","model":"Könnten Sie mir bitte helfen?","why":"Only the infinitive helfen is required at the end."},{"id":"G17-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"in/vor/nach + time; Könnten Sie ... + infinitive?","model":"Ich komme in zehn Minuten.","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G17-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Vor einer Woche war ich krank.","model":"Example starting point: Könnten Sie mir bitte helfen?","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":18,"level":"A1.2","title":"wollen, werden, mit and ohne","goal":"Express plans, change and accompaniment.","formula":"subject + will + details + infinitive","explanations":["wollen expresses intention. werden can describe becoming something or changing state.","mit takes the dative; ohne always takes the accusative. Contrast mit dem Bus and ohne einen Regenschirm."],"notes":["wollen is about intention, not the only way to speak about future plans.","werden as a main verb means become; don't use it for every future plan at A1.","mit takes dative (mit meinem Freund); ohne takes accusative (ohne meinen Freund).","Modal forms are irregular: ich will, du willst, er will."],"examples":[{"de":"Wir wollen im Sommer verreisen.","en":"We want to travel in summer."},{"de":"Es wird am Abend dunkel.","en":"It gets dark in the evening."},{"de":"Ich gehe ohne meinen Rucksack.","en":"I'm going without my backpack."}],"trap":{"wrong":"Ich will morgen gehe arbeiten.","correct":"Ich will morgen arbeiten gehen.","why":"The modal structure keeps its infinitives at the end."},"challenge":"State three plans, one change in the weather and one journey with/without something.","questions":[{"id":"G18-01","step":18,"kind":"mc","prompt":"Wir ___ heute früh gehen.","answer":"wollen","explanation":"wir uses wollen.","options":["wollen","will","wollt"]},{"id":"G18-02","step":18,"kind":"mc","prompt":"Er ___ später Arzt.","answer":"wird","explanation":"er wird = he becomes.","options":["wird","werde","werden"]},{"id":"G18-03","step":18,"kind":"mc","prompt":"Ich gehe ___ meinen Hund.","answer":"ohne","explanation":"meinen is accusative, and ohne always takes the accusative: ohne meinen Hund. With mit it would be mit meinem Hund (dative).","options":["ohne","mit","bei"],"corrected":true},{"id":"G18-04","step":18,"kind":"mc","prompt":"Sie fährt ___ dem Fahrrad.","answer":"mit","explanation":"With a vehicle: mit + dative.","options":["mit","ohne","zu"]},{"id":"G18-05","step":18,"kind":"mc","prompt":"Du ___ etwas Neues lernen.","answer":"willst","explanation":"du willst is irregular.","options":["willst","wollst","will"]},{"id":"G18-06","step":18,"kind":"mc","prompt":"Es ___ immer wärmer.","answer":"wird","explanation":"werden describes change.","options":["wird","will","werden"]},{"id":"G18-F1","step":18,"kind":"fill","prompt":"Ich ___ heute nicht ausgehen. (want)","answer":"will","explanation":"ich will."},{"id":"G18-F2","step":18,"kind":"fill","prompt":"Sie fährt ___ dem Auto.","answer":"mit","explanation":"mit + dative."}],"tasks":[{"id":"G18-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Ich will morgen gehe arbeiten.","model":"Ich will morgen arbeiten gehen.","why":"The modal structure keeps its infinitives at the end."},{"id":"G18-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"subject + will + details + infinitive","model":"Wir wollen im Sommer verreisen.","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G18-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Es wird am Abend dunkel.","model":"Example starting point: Ich gehe ohne meinen Rucksack.","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":19,"level":"A1.2","title":"Polite commands and sollen","goal":"Give formal instructions and relay advice or obligations.","formula":"verb (infinitive) + Sie + ... + bitte","explanations":["The polite imperative uses the infinitive plus Sie: Kommen Sie bitte herein!","sollen expresses advice/instructions from another person; the main verb remains in the infinitive at the end."],"notes":["Polite imperative: infinitive first, then Sie. Adding bitte makes it friendlier.","Do not confuse a polite command with a declarative sentence ending in Sie.","sollen often reports advice or instructions from a doctor or another person.","With sollen, the infinitive still stays at the end."],"examples":[{"de":"Warten Sie bitte einen Moment!","en":"Please wait a moment."},{"de":"Sprechen Sie bitte langsamer.","en":"Please speak more slowly."},{"de":"Ich soll morgen zum Arzt gehen.","en":"I'm supposed to go to the doctor tomorrow."}],"trap":{"wrong":"Wartet Sie bitte hier!","correct":"Warten Sie bitte hier!","why":"The polite command uses the infinitive Warten followed by Sie."},"challenge":"Write three courteous signs for a classroom, office or waiting room.","questions":[{"id":"G19-01","step":19,"kind":"mc","prompt":"___ Sie bitte herein!","answer":"Kommen","explanation":"Polite imperative uses infinitive + Sie.","options":["Kommen","Kommt","Komm"]},{"id":"G19-02","step":19,"kind":"mc","prompt":"___ Sie bitte Platz!","answer":"Nehmen","explanation":"Polite imperative: Nehmen Sie ...","options":["Nehmen","Nimm","Nehmt"]},{"id":"G19-03","step":19,"kind":"mc","prompt":"Du ___ heute viel trinken.","answer":"sollst","explanation":"du sollst means you should.","options":["sollst","sollen","soll"]},{"id":"G19-04","step":19,"kind":"mc","prompt":"Wir ___ die Ärztin anrufen.","answer":"sollen","explanation":"wir sollen + infinitive.","options":["sollen","sollst","soll"]},{"id":"G19-05","step":19,"kind":"mc","prompt":"___ Sie bitte hier!","answer":"Warten","explanation":"Polite imperative: Warten Sie.","options":["Warten","Wartest","Wartet"]},{"id":"G19-06","step":19,"kind":"mc","prompt":"Herr Weber, Sie ___ morgen pünktlich sein.","answer":"sollen","explanation":"Polite Sie takes sollen.","options":["sollen","soll","sollst"],"corrected":true},{"id":"G19-F1","step":19,"kind":"fill","prompt":"___ Sie bitte die Tür! (open)","answer":"Öffnen","explanation":"Formal imperative: infinitive + Sie."},{"id":"G19-F2","step":19,"kind":"fill","prompt":"Du ___ mehr schlafen. (should)","answer":"sollst","explanation":"du sollst."}],"tasks":[{"id":"G19-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Wartet Sie bitte hier!","model":"Warten Sie bitte hier!","why":"The polite command uses the infinitive Warten followed by Sie."},{"id":"G19-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"verb (infinitive) + Sie + ... + bitte","model":"Warten Sie bitte einen Moment!","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G19-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Sprechen Sie bitte langsamer.","model":"Example starting point: Ich soll morgen zum Arzt gehen.","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":20,"level":"A1.2","title":"Informal commands and object pronouns","goal":"Give du/ihr instructions and replace objects with pronouns.","formula":"du imperative: Komm!; ihr imperative: Kommt!","explanations":["The informal du imperative often uses the verb stem, while ihr uses the familiar ihr verb form without ihr.","Accusative personal pronouns include mich, dich, ihn, sie, es, uns, euch and sie/Sie."],"notes":["Imperatives in du and ihr use different verb forms; the subject is omitted.","Objects are replaced by pronouns that match the object's grammatical gender and case.","mich/dich/ihn answer Wen?; mir/dir/ihm answer Wem? (dative).","Some verbs have irregular du commands, e.g. Lies! or Nimm!"],"examples":[{"de":"Lies bitte die Nachricht!","en":"Please read the message!"},{"de":"Nehmt eure Bücher mit!","en":"Take your books with you!"},{"de":"Ich sehe den Hund. Ich sehe ihn.","en":"I see the dog. I see it."}],"trap":{"wrong":"Du komm bitte!","correct":"Komm bitte!","why":"The du subject is normally omitted in the imperative."},"challenge":"Make two requests to a friend and two to a group, then replace three objects with pronouns.","questions":[{"id":"G20-01","step":20,"kind":"mc","prompt":"___ bitte die Tür! (du)","answer":"Schließ","explanation":"The du imperative uses the stem: Schließ (or Schließe) bitte die Tür!","options":["Schließ","Schließt","Schließen"]},{"id":"G20-02","step":20,"kind":"mc","prompt":"___ bitte leise! (ihr)","answer":"Sprecht","explanation":"ihr imperative matches ihr form.","options":["Sprecht","Sprich","Sprechen"]},{"id":"G20-03","step":20,"kind":"mc","prompt":"Ich höre den Mann. Ich höre ___.","answer":"ihn","explanation":"Masculine accusative pronoun: ihn.","options":["ihn","er","ihm"]},{"id":"G20-04","step":20,"kind":"mc","prompt":"Kannst du ___ sehen? (me)","answer":"mich","explanation":"sehen takes accusative: mich.","options":["mich","mir","ich"]},{"id":"G20-05","step":20,"kind":"mc","prompt":"___ eure Bücher mit! (ihr)","answer":"Nehmt","explanation":"ihr imperative: Nehmt.","options":["Nehmt","Nimm","Nehmen"]},{"id":"G20-06","step":20,"kind":"mc","prompt":"___ langsam! (du)","answer":"Fahr","explanation":"Common du imperative: Fahr.","options":["Fahr","Fährst","Fahrt"]},{"id":"G20-F1","step":20,"kind":"fill","prompt":"___ bitte her! (come, du)","answer":"Komm","explanation":"Du imperative Komm!","accept":["Komme"],"corrected":true},{"id":"G20-F2","step":20,"kind":"fill","prompt":"Wir sehen den Mann. Wir sehen ___.","answer":"ihn","explanation":"Masculine accusative pronoun."}],"tasks":[{"id":"G20-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Du komm bitte!","model":"Komm bitte!","why":"The du subject is normally omitted in the imperative."},{"id":"G20-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"du imperative: Komm!; ihr imperative: Kommt!","model":"Lies bitte die Nachricht!","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G20-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Nehmt eure Bücher mit!","model":"Example starting point: Ich sehe den Hund. Ich sehe ihn.","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":21,"level":"A1.2","title":"Past participles without ge-","goal":"Recognize common inseparable-prefix participles and the prefix un-.","formula":"haben/sein + ... + participle without ge-","explanations":["Verbs beginning be-, ver- or er- form participles without ge-, e.g. bezahlt, verstanden, erzählt.","Adjectives with un- often express the opposite: möglich/unmöglich, pünktlich/unpünktlich."],"notes":["Prefixes be-, ver- and er- are typically inseparable: their participles omit ge-.","A typical regular past participle ends -t even without ge-: bezahlt.","Un- can make an adjective's opposite, but not all adjectives allow it.","Watch bekommen: its participle is bekommen, not gebekommen."],"examples":[{"de":"Ich habe die Rechnung bezahlt.","en":"I paid the bill."},{"de":"Wir haben die Aufgabe verstanden.","en":"We understood the task."},{"de":"Der Termin ist unmöglich.","en":"The appointment is impossible."}],"trap":{"wrong":"Ich habe die Geschichte geerzählt.","correct":"Ich habe die Geschichte erzählt.","why":"An er- verb does not take extra ge- in the participle."},"challenge":"Explain a past problem in four sentences using two inseparable-prefix verbs.","questions":[{"id":"G21-01","step":21,"kind":"mc","prompt":"Ich habe die E-Mail ___.","answer":"beantwortet","explanation":"be- verbs usually take no extra ge-.","options":["beantwortet","gebeantwortet","antworten"]},{"id":"G21-02","step":21,"kind":"mc","prompt":"Sie hat die Geschichte ___.","answer":"erzählt","explanation":"er- verbs form participles without ge-.","options":["erzählt","geerzählt","erzählen"]},{"id":"G21-03","step":21,"kind":"mc","prompt":"Wir haben den Zug ___.","answer":"verpasst","explanation":"ver- verbs do not use ge-.","options":["verpasst","geverpasst","verpassen"]},{"id":"G21-04","step":21,"kind":"mc","prompt":"Heute ist es ___. (not possible)","answer":"unmöglich","explanation":"un- can form the opposite adjective.","options":["unmöglich","nichtmöglich","unmöglichen"]},{"id":"G21-05","step":21,"kind":"mc","prompt":"Er ist leider ___. (not punctual)","answer":"unpünktlich","explanation":"un- forms the negative adjective.","options":["unpünktlich","pünktlich","unpunkten"]},{"id":"G21-06","step":21,"kind":"mc","prompt":"Hast du alles ___?","answer":"verstanden","explanation":"verstehen -> verstanden.","options":["verstanden","geverstanden","verstehen"]},{"id":"G21-F1","step":21,"kind":"fill","prompt":"Er hat das Paket ___. (receive)","answer":"bekommen","explanation":"bekommen -> bekommen."},{"id":"G21-F2","step":21,"kind":"fill","prompt":"Sie hat den Schlüssel ___. (lose)","answer":"verloren","explanation":"verlieren -> verloren, without ge-."}],"tasks":[{"id":"G21-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Ich habe die Geschichte geerzählt.","model":"Ich habe die Geschichte erzählt.","why":"An er- verb does not take extra ge- in the participle."},{"id":"G21-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"haben/sein + ... + participle without ge-","model":"Ich habe die Rechnung bezahlt.","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G21-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Wir haben die Aufgabe verstanden.","model":"Example starting point: Der Termin ist unmöglich.","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":22,"level":"A1.2","title":"müssen, dürfen, man and modal contrast","goal":"Distinguish necessity, permission and prohibition.","formula":"man darf/muss/kann + ... + infinitive","explanations":["müssen means must or have to. dürfen means may or be allowed. nicht dürfen means prohibited; nicht müssen means not necessary.","man is an impersonal subject (one/people in general), and takes third-person singular verbs."],"notes":["müssen + nicht expresses no obligation: you may, but you don't have to.","dürfen + nicht means forbidden; this is stronger than a lack of obligation.","man is grammatically third-person singular: man darf, man muss.","Use wollen for intention, können for ability, dürfen for permission, sollen for advice."],"examples":[{"de":"Hier darf man nicht parken.","en":"Parking is not allowed here."},{"de":"Du musst heute nicht kommen.","en":"You don't have to come today."},{"de":"Wir müssen pünktlich sein.","en":"We must be punctual."}],"trap":{"wrong":"Du musst hier nicht rauchen (forbidden).","correct":"Du darfst hier nicht rauchen.","why":"Prohibition requires nicht dürfen, not nicht müssen."},"challenge":"Describe three rules and three permissions at work, school or in your building.","questions":[{"id":"G22-01","step":22,"kind":"mc","prompt":"Hier ___ man nicht rauchen.","answer":"darf","explanation":"nicht dürfen expresses prohibition.","options":["darf","muss","will"]},{"id":"G22-02","step":22,"kind":"mc","prompt":"Du ___ nicht mitkommen. (not necessary)","answer":"musst","explanation":"nicht müssen means not necessary.","options":["musst","darfst","kannst"]},{"id":"G22-03","step":22,"kind":"mc","prompt":"Wir ___ heute lernen. (necessary)","answer":"müssen","explanation":"müssen expresses necessity.","options":["müssen","dürfen","mögen"]},{"id":"G22-04","step":22,"kind":"mc","prompt":"___ ich hier parken? (permission)","answer":"Darf","explanation":"Darf ich ...? asks permission.","options":["Darf","Muss","Kannst"]},{"id":"G22-05","step":22,"kind":"mc","prompt":"Man ___ hier leise sein.","answer":"muss","explanation":"man uses third-person singular.","options":["muss","müssen","musst"]},{"id":"G22-06","step":22,"kind":"mc","prompt":"Ihr ___ jetzt gehen. (permitted)","answer":"dürft","explanation":"ihr dürft is permission.","options":["dürft","darf","dürfen"]},{"id":"G22-F1","step":22,"kind":"fill","prompt":"Du ___ hier nicht parken. (forbidden)","answer":"darfst","explanation":"nicht dürfen indicates prohibition."},{"id":"G22-F2","step":22,"kind":"fill","prompt":"Wir ___ heute nicht arbeiten. (not required)","answer":"müssen","explanation":"nicht müssen indicates no obligation."}],"tasks":[{"id":"G22-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Du musst hier nicht rauchen (forbidden).","model":"Du darfst hier nicht rauchen.","why":"Prohibition requires nicht dürfen, not nicht müssen."},{"id":"G22-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"man darf/muss/kann + ... + infinitive","model":"Hier darf man nicht parken.","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G22-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Du musst heute nicht kommen.","model":"Example starting point: Wir müssen pünktlich sein.","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":23,"level":"A1.2","title":"Comparisons and demonstratives","goal":"Compare things with als/wie and choose welche/diese forms.","formula":"adjective-er + als; so + adjective + wie","explanations":["Comparative adjectives often add -er; equal comparisons use so ... wie, unequal comparisons use comparative + als.","welch- asks which; dies- means this/these. Their endings depend on the noun and its case."],"notes":["The comparison adjective follows its own patterns: groß -> größer; gut -> besser.","Use als with a difference and wie with equal degree: so groß wie.","Superlatives with am often end -sten: am schnellsten.","welch- asks for a choice and dies- points out a particular item; endings matter."],"examples":[{"de":"Mein Zimmer ist heller als deins.","en":"My room is brighter than yours."},{"de":"Dieses Kleid ist genauso teuer wie das andere.","en":"This dress is just as expensive as the other."},{"de":"Welche Tasche möchtest du?","en":"Which bag would you like?"}],"trap":{"wrong":"Dieser Buch ist neu.","correct":"Dieses Buch ist neu.","why":"Buch is neuter; use dieses in nominative."},"challenge":"Compare two apartments or products with four different adjectives.","questions":[{"id":"G23-01","step":23,"kind":"mc","prompt":"Mein Rucksack ist ___ als deiner.","answer":"schwerer","explanation":"With als use comparative -er.","options":["schwerer","schwer","am schwersten"]},{"id":"G23-02","step":23,"kind":"mc","prompt":"Das Auto ist so groß ___ der Bus.","answer":"wie","explanation":"so ... wie expresses equality.","options":["wie","als","von"]},{"id":"G23-03","step":23,"kind":"mc","prompt":"___ Buch gehört dir?","answer":"Welches","explanation":"Buch is neuter nominative.","options":["Welches","Welcher","Welche"]},{"id":"G23-04","step":23,"kind":"mc","prompt":"Ich nehme ___ Pullover.","answer":"diesen","explanation":"Masculine accusative: diesen.","options":["diesen","dieser","dieses"]},{"id":"G23-05","step":23,"kind":"mc","prompt":"Dieses Fahrrad ist ___ als das alte.","answer":"besser","explanation":"gut -> besser.","options":["besser","guter","am besten"]},{"id":"G23-06","step":23,"kind":"mc","prompt":"Welche Schuhe sind ___? (cheapest)","answer":"am billigsten","explanation":"Superlative with am: am billigsten.","options":["am billigsten","billiger","billig"]},{"id":"G23-F1","step":23,"kind":"fill","prompt":"Dieses Haus ist ___ als das alte. (large)","answer":"größer","explanation":"Comparative of groß."},{"id":"G23-F2","step":23,"kind":"fill","prompt":"Welch___ Mantel möchtest du? (accusative masculine)","answer":"en","explanation":"welchen Mantel.","accept":["welchen"],"corrected":true}],"tasks":[{"id":"G23-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Dieser Buch ist neu.","model":"Dieses Buch ist neu.","why":"Buch is neuter; use dieses in nominative."},{"id":"G23-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"adjective-er + als; so + adjective + wie","model":"Mein Zimmer ist heller als deins.","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G23-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Dieses Kleid ist genauso teuer wie das andere.","model":"Example starting point: Welche Tasche möchtest du?","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":24,"level":"A1.2","title":"Connectors and two-way prepositions","goal":"Link ideas and distinguish location from direction.","formula":"und/aber/oder/denn + normal main clause","explanations":["und, aber, oder and denn join main clauses without moving the finite verb to the end.","Two-way prepositions such as in/auf/an use dative for location (wo?) and accusative for destination (wohin?)."],"notes":["Connectors und, aber, oder, denn join full main clauses without changing verb-second order.","For place prepositions ask Wo? (location) or Wohin? (movement to a place).","auf dem Tisch describes position; auf den Tisch describes placement.","Some verbs pair with physical states: liegen/legen and stehen/stellen."],"examples":[{"de":"Ich bleibe zu Hause, denn ich bin müde.","en":"I'm staying home because I'm tired."},{"de":"Das Buch liegt auf dem Tisch.","en":"The book is lying on the table."},{"de":"Ich lege das Buch auf den Tisch.","en":"I put the book on the table."}],"trap":{"wrong":"Ich gehe in der Küche hinein.","correct":"Ich gehe in die Küche.","why":"For motion into a location, use accusative."},"challenge":"Explain where three things are and where you move them; connect two thoughts with denn.","questions":[{"id":"G24-01","step":24,"kind":"mc","prompt":"Ich bin zu Hause, ___ ich bin krank.","answer":"denn","explanation":"denn gives a reason and keeps main clause order.","options":["denn","oder","und"]},{"id":"G24-02","step":24,"kind":"mc","prompt":"Das Handy liegt auf ___ Tisch.","answer":"dem","explanation":"Wo? -> dative masculine.","options":["dem","den","der"]},{"id":"G24-03","step":24,"kind":"mc","prompt":"Ich lege das Handy auf ___ Tisch.","answer":"den","explanation":"Wohin? -> accusative masculine.","options":["den","dem","der"]},{"id":"G24-04","step":24,"kind":"mc","prompt":"Wir gehen ___ Kino.","answer":"ins","explanation":"Destination into Kino: ins.","options":["ins","im","ans"]},{"id":"G24-05","step":24,"kind":"mc","prompt":"Wir sitzen ___ Kino.","answer":"im","explanation":"Location in Kino: im.","options":["im","ins","in die"]},{"id":"G24-06","step":24,"kind":"mc","prompt":"Ist der Tee heiß ___ kalt?","answer":"oder","explanation":"oder offers a choice.","options":["oder","denn","aber"]},{"id":"G24-F1","step":24,"kind":"fill","prompt":"Das Bild hängt an ___ Wand. (the, location)","answer":"der","explanation":"Wo? feminine dative."},{"id":"G24-F2","step":24,"kind":"fill","prompt":"Ich hänge das Bild an ___ Wand. (the, destination)","answer":"die","explanation":"Wohin? feminine accusative."}],"tasks":[{"id":"G24-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Ich gehe in der Küche hinein.","model":"Ich gehe in die Küche.","why":"For motion into a location, use accusative."},{"id":"G24-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"und/aber/oder/denn + normal main clause","model":"Ich bleibe zu Hause, denn ich bin müde.","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G24-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Das Buch liegt auf dem Tisch.","model":"Example starting point: Ich lege das Buch auf den Tisch.","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]},{"n":25,"level":"A1.2","title":"Dates, ordinal numbers and würde","goal":"Say dates and express wishes politely.","formula":"am + ordinal ending; würde + gern + infinitive","explanations":["Ordinal numbers name an order or a calendar date: der erste Mai; am ersten Mai.","würde + infinitive expresses polite or hypothetical wishes: Ich würde gern ... . It is an extension useful at the end of A1."],"notes":["Ordinal numbers indicate rank or dates, not basic quantities.","Without am say der erste Mai; after am say am ersten Mai.","würde + infinitive is a polite or hypothetical wish rather than ordinary future.","Learn months, numbers and their spoken forms together as one package."],"examples":[{"de":"Heute ist der vierte April.","en":"Today is the fourth of April."},{"de":"Mein Termin ist am siebten Juni.","en":"My appointment is on June seventh."},{"de":"Ich würde gern mehr reisen.","en":"I would like to travel more."}],"trap":{"wrong":"Ich habe am drei Mai Geburtstag.","correct":"Ich habe am dritten Mai Geburtstag.","why":"After am, use the dative ordinal ending -en."},"challenge":"Tell three important dates and write a wish list with würde gern.","questions":[{"id":"G25-01","step":25,"kind":"mc","prompt":"Heute ist der ___ Juli. (1st)","answer":"erste","explanation":"Nominative date: der erste.","options":["erste","ersten","eins"]},{"id":"G25-02","step":25,"kind":"mc","prompt":"Mein Termin ist am ___ Juli. (1st)","answer":"ersten","explanation":"am + ordinal takes -en.","options":["ersten","erste","eins"]},{"id":"G25-03","step":25,"kind":"mc","prompt":"Wir feiern am ___ Mai. (3rd)","answer":"dritten","explanation":"am dritten Mai.","options":["dritten","dritte","drei"]},{"id":"G25-04","step":25,"kind":"mc","prompt":"Ich ___ gern in Österreich wohnen.","answer":"würde","explanation":"würde + infinitive expresses a wish.","options":["würde","wurde","werden"]},{"id":"G25-05","step":25,"kind":"mc","prompt":"___ du gern mehr reisen?","answer":"Würdest","explanation":"du takes würdest.","options":["Würdest","Würden","Würde"]},{"id":"G25-06","step":25,"kind":"mc","prompt":"Morgen ist der ___ Februar. (2nd)","answer":"zweite","explanation":"der zweite Februar is nominative.","options":["zweite","zweiten","zwei"]},{"id":"G25-F1","step":25,"kind":"fill","prompt":"Mein Geburtstag ist am ___ Juni. (fourth)","answer":"vierten","explanation":"am + dative ordinal."},{"id":"G25-F2","step":25,"kind":"fill","prompt":"Ich ___ gern Deutsch flüssig sprechen. (would)","answer":"würde","explanation":"würde + infinitive."}],"tasks":[{"id":"G25-T1","type":"correction","prompt":"Spot and repair the grammar mistake:","question":"Ich habe am drei Mai Geburtstag.","model":"Ich habe am dritten Mai Geburtstag.","why":"After am, use the dative ordinal ending -en."},{"id":"G25-T2","type":"sentence_production","prompt":"Explain this pattern aloud. Then write a new sentence using it:","question":"am + ordinal ending; würde + gern + infinitive","model":"Heute ist der vierte April.","why":"Compare your verb position, case endings and meaning to the model."},{"id":"G25-T3","type":"variation","prompt":"Change the person, place or time while keeping the grammar correct:","question":"Mein Termin ist am siebten Juni.","model":"Example starting point: Ich würde gern mehr reisen.","why":"Many answers are valid; check the grammar, not word-for-word similarity."}]}],"checkpoints":[{"n":1,"after":5,"title":"Checkpoint 1 — Steps 1–5","from":1,"ids":["G01-01","G01-03","G02-01","G02-03","G03-01","G03-03","G04-01","G04-03","G05-01","G05-03"]},{"n":2,"after":10,"title":"Checkpoint 2 — Steps 6–10","from":6,"ids":["G06-01","G06-03","G07-01","G07-03","G08-01","G08-03","G09-01","G09-03","G10-01","G10-03"]},{"n":3,"after":15,"title":"Checkpoint 3 — Steps 11–15","from":11,"ids":["G11-01","G11-03","G12-01","G12-03","G13-01","G13-03","G14-01","G14-03","G15-01","G15-03"]},{"n":4,"after":20,"title":"Checkpoint 4 — Steps 16–20","from":16,"ids":["G16-01","G16-03","G17-01","G17-03","G18-01","G18-03","G19-01","G19-03","G20-01","G20-03"]},{"n":5,"after":25,"title":"Checkpoint 5 — Steps 21–25","from":21,"ids":["G21-01","G21-03","G22-01","G22-03","G23-01","G23-03","G24-01","G24-03","G25-01","G25-03"]}],"counts":{"steps":25,"questions":200,"tasks":75,"checkpoints":5}};
